#include "stdlib/lapack/base/dlaset.h"
#include "stdlib/lapack/base/shared.h"
#include "stdlib/lapack/base/xerbla.h"

/**
* Sets the off-diagonal elements and the diagonal elements of a double-precision floating-point matrix to specified values.
*
* @param layout   storage layout
* @param uplo     specifies whether to set the upper or lower triangular/trapezoidal part of matrix `A`
* @param M        number of rows in matrix `A`
* @param N        number of columns in matrix `A`
* @param alpha    value assigned to off-diagonal elements
* @param beta     value assigned to diagonal elements
* @param A        input matrix
* @param LDA      stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A`)
* @return         status code
*/
LAPACK_INT API_SUFFIX(c_dlaset)( const LAPACK_LAYOUT layout, const int uplo, const LAPACK_INT M, const LAPACK_INT N, const double alpha, const double beta, double *A, const LAPACK_INT LDA ) {
	LAPACK_INT sa1;
	LAPACK_INT sa2;

	// Perform input argument validation...
	if ( layout != LAPACK_ROW_MAJOR && layout != LAPACK_COL_MAJOR ) {
		lapack_xerbla( "c_dlaset", -1 );
		return -1;
	}
	if ( layout == LAPACK_COL_MAJOR ) {
		sa1 = 1;
		sa2 = LDA;
	} else { // layout == CblasRowMajor
		sa1 = LDA;
		sa2 = 1;
	}
	return API_SUFFIX(c_dlaset_ndarray)( uplo, M, N, alpha, beta, A, sa1, sa2, 0 );
}
